const http = require('http');

const projectRoot = $vars.projectRoot || '.';
const authToken = $vars.authToken || '';

const filePath = typeof $path !== 'undefined' ? $path : '';
if (!filePath) return 'Error: path is required';

// Если путь указывает на директорию - используем list_files вместо read_file
const isDirPath = filePath === '.' || filePath === '/' || filePath === './' || filePath.endsWith('/');
const baseUrl = isDirPath
  ? 'http://localhost:3001/mcp/list_files'
  : 'http://localhost:3001/mcp/read_file';

const body = isDirPath
  ? JSON.stringify({ parameters: { path: '.', recursive: false } })
  : JSON.stringify({ parameters: { path: filePath } });

return new Promise((resolve) => {
  const req = http.request(baseUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
      'Authorization': 'Bearer ' + authToken,
      'X-Project-Root': encodeURIComponent(projectRoot)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      if (res.statusCode !== 200) {
        resolve('Error: ' + res.statusCode + ' - ' + data.slice(0, 200));
      } else {
        try {
          const json = JSON.parse(data);
          if (isDirPath && json.success && json.data?.files) {
            const fileList = json.data.files.map(f => f.path + ' (' + f.type + ')').join('\n');
            resolve('Project files:\n' + fileList);
          } else {
            resolve(json.data?.content || data);
          }
        } catch {
          resolve(data);
        }
      }
    });
  });

  req.on('error', (err) => resolve('Error: ' + err.message));
  req.write(body);
  req.end();
});
